  $payload${"title":"Evaluación: Diagnósticos Diferenciales y Trampas de ELA","revisionType":"quiz","quizTopicId":"als-mimics","moduleId":"diagnostic-criteria","passScore":70,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"q1","type":"true_false","difficulty":"basic","stem":"NMM: bloqueos motor + SNAP normal + anti-GM1 → TRATABLE (¡no confundir con ELA!). ¿Esta afirmación es la que corresponde enseñar en «Diagnósticos Diferenciales y Trampas de ELA»?","options":[{"id":"a","text":"Sí. Esa es la conducta que describe la lección.","isCorrect":true},{"id":"b","text":"No. La lección sostiene lo contrario.","isCorrect":false}],"explanation":"NMM: bloqueos motor + SNAP normal + anti-GM1 → TRATABLE (¡no confundir con ELA!).\n\n📚 Referencia: Shefner JM, Al-Chalabi A, Baker MR, et al.. A proposal for new diagnostic criteria for ALS (Gold Coast criteria). Clinical Neurophysiology (2020). https://pubmed.ncbi.nlm.nih.gov/32387049/","citations":[]},{"id":"q2","type":"single","difficulty":"intermediate","stem":"En «Diagnósticos Diferenciales y Trampas de ELA», ¿cuál afirmación es la correcta?\nKennedy: SNAPs ANORMALES + LMN + ginecomastia → genética CAG.","options":[{"id":"a","text":"Kennedy: SNAPs ANORMALES + LMN + ginecomastia → genética CAG.","isCorrect":true},{"id":"b","text":"Un valor aislado, sin repetir el trazo, basta para cerrar el diagnóstico.","isCorrect":false},{"id":"c","text":"La temperatura de la extremidad puede ignorarse si el número ya es extremo.","isCorrect":false},{"id":"d","text":"Medir sobre el artefacto de estímulo es aceptable si la amplitud se ve estable.","isCorrect":false}],"explanation":"Kennedy: SNAPs ANORMALES + LMN + ginecomastia → genética CAG.\n\n📚 Referencia: Shefner JM, Al-Chalabi A, Baker MR, et al.. A proposal for new diagnostic criteria for ALS (Gold Coast criteria). Clinical Neurophysiology (2020). https://pubmed.ncbi.nlm.nih.gov/32387049/","citations":[]},{"id":"q3","type":"single","difficulty":"advanced","stem":"En «Diagnósticos Diferenciales y Trampas de ELA», ¿cuál afirmación es la correcta?\nMielopatía cervical: UMN piernas + LMN manos, solo 1 región → RM.","options":[{"id":"a","text":"Mielopatía cervical: UMN piernas + LMN manos, solo 1 región → RM.","isCorrect":true},{"id":"b","text":"Un valor aislado, sin repetir el trazo, basta para cerrar el diagnóstico.","isCorrect":false},{"id":"c","text":"La temperatura de la extremidad puede ignorarse si el número ya es extremo.","isCorrect":false},{"id":"d","text":"Medir sobre el artefacto de estímulo es aceptable si la amplitud se ve estable.","isCorrect":false}],"explanation":"Mielopatía cervical: UMN piernas + LMN manos, solo 1 región → RM.\n\n📚 Referencia: Shefner JM, Al-Chalabi A, Baker MR, et al.. A proposal for new diagnostic criteria for ALS (Gold Coast criteria). Clinical Neurophysiology (2020). https://pubmed.ncbi.nlm.nih.gov/32387049/","citations":[]},{"id":"q4","type":"single","difficulty":"advanced","stem":"En «Diagnósticos Diferenciales y Trampas de ELA», ¿cuál afirmación es la correcta?\nFasciculaciones aisladas SIN denervación activa ≠ ELA.","options":[{"id":"a","text":"Fasciculaciones aisladas SIN denervación activa ≠ ELA.","isCorrect":true},{"id":"b","text":"Un valor aislado, sin repetir el trazo, basta para cerrar el diagnóstico.","isCorrect":false},{"id":"c","text":"La temperatura de la extremidad puede ignorarse si el número ya es extremo.","isCorrect":false},{"id":"d","text":"Medir sobre el artefacto de estímulo es aceptable si la amplitud se ve estable.","isCorrect":false}],"explanation":"Fasciculaciones aisladas SIN denervación activa ≠ ELA.\n\n📚 Referencia: Shefner JM, Al-Chalabi A, Baker MR, et al.. A proposal for new diagnostic criteria for ALS (Gold Coast criteria). Clinical Neurophysiology (2020). https://pubmed.ncbi.nlm.nih.gov/32387049/","citations":[]}],"examQuestions":[{"module_id":"diagnostic-criteria","topic_id":"als-mimics","topic_name":"Diagnósticos Diferenciales y Trampas de ELA","island_name":"EMG","stem":"Caso breve ligado a «Diagnósticos Diferenciales y Trampas de ELA». NMM: bloqueos motor + SNAP normal + anti-GM1 → TRATABLE (¡no confundir con ELA!). ¿Cuál es la conducta correcta?","findings":[],"options":[{"text":"NMM: bloqueos motor + SNAP normal + anti-GM1 → TRATABLE (¡no confundir con ELA!).","is_correct":true,"feedback":"Coincide con el texto de la lección."},{"text":"Cerrar el diagnóstico con un solo parámetro no reproducido.","is_correct":false,"feedback":"Un parámetro aislado no cierra la topografía."},{"text":"Ignorar temperatura y distancia.","is_correct":false,"feedback":"Temperatura y distancia cambian latencia y velocidad."},{"text":"Medir la latencia sobre el artefacto de estímulo.","is_correct":false,"feedback":"El onset dentro del artefacto no es una latencia."}],"difficulty":2,"is_critical":false,"pearl":"REGLA DE ORO ante sospecha de ELA: SIEMPRE descartar NMM antes de dar el diagnóstico. Solicitar NCS completas buscando bloqueos de conducción + anti-GM1. La NMM es tratable y su confusión con ELA es un error inaceptable.","source_reference":"Shefner JM, Al-Chalabi A, Baker MR, et al.. A proposal for new diagnostic criteria for ALS (Gold Coast criteria). Clinical Neurophysiology (2020). https://pubmed.ncbi.nlm.nih.gov/32387049/","tags":["diagnostic-criteria","als-mimics"],"status":"DRAFT"}]}$payload$::jsonb,
